// 获取AI分析结果和原始数据
const aiAnalysis = $input.first().json.output;
const originalData = $('接收POST请求').first().json.body;

// 合并数据
const processedData = {
  originalData,
  aiAnalysis,
  // 添加时间戳
  received_at: new Date().toISOString(),
  // 生成工单ID
  ticket_id: 'T' + Date.now() + Math.random().toString(36).substr(2, 5)
};

// 决策逻辑
let action = 'normal';

if (aiAnalysis.true_urgency === 'critical' || 
    aiAnalysis.sentiment === 'angry' ||
    aiAnalysis.requires_immediate_human_intervention) {
  action = 'urgent';
} else if (aiAnalysis.true_urgency === 'low') {
    action = 'auto_reply';
}

processedData.action_required = action;

// 返回处理后的数据
return [{ json: processedData }];

