// 假设输入数据为 items[0].json.content
const content = $input.first().json.output;

// 1. 去除首尾空白
// 2. 替换所有换行符为 \\n
// 3. 替换所有制表符为一个空格（可选，根据需要）
const compressed = content.trim().replace(/\n/g, '\\n').replace(/\t/g, ' ');

return [
  {
    json: {
      compressedContent: compressed
    }
  }
];

